const VER='2.2',REL=!!document.querySelector('link[rel=manifest]');
function fsOn(){return !!(document.fullscreenElement||document.webkitFullscreenElement);}
function fsCan(){return !!(document.fullscreenEnabled||document.webkitFullscreenEnabled);}
async function goLand(){if(!fsCan())return false;try{const el=document.documentElement;if(!fsOn())await (el.requestFullscreen?el.requestFullscreen({navigationUI:'hide'}):el.webkitRequestFullscreen());if(screen.orientation&&screen.orientation.lock)await screen.orientation.lock('landscape');return true;}catch(e){return false;}}
async function fsToggle(){try{if(fsOn()){if(screen.orientation&&screen.orientation.unlock)screen.orientation.unlock();await (document.exitFullscreen?document.exitFullscreen():document.webkitExitFullscreen());}else{const el=document.documentElement;await (el.requestFullscreen?el.requestFullscreen({navigationUI:'hide'}):el.webkitRequestFullscreen());if(oriGet()==='rot'&&screen.orientation&&screen.orientation.lock)screen.orientation.lock('landscape').catch(()=>{});}}catch(e){toast(L('Tarayıcın tam ekrana izin vermedi','Your browser didn’t allow full screen','浏览器不允许全屏'),'','warn');}setTimeout(applyOri,250);}
function exportSave(){if(!S)return;try{const blob=new Blob([JSON.stringify(S)],{type:'application/json'}),a=document.createElement('a'),nm=(S.name||'kayit').toLocaleLowerCase('tr').replace(/[^a-z0-9çğıöşü]+/g,'-').replace(/^-|-$/g,'');a.href=URL.createObjectURL(blob);a.download='armator-'+(nm||'save')+'-'+Math.floor(S.day)+'.json';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},800);toast(L('Kayıt dosyası indirildi','Save file downloaded','存档文件已下载'),'','ok');}catch(e){toast(L('Kayıt indirilemedi','Couldn’t download the save','无法下载存档'),'','bad');}}
function importSave(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const o=JSON.parse(r.result);if(!o||o.v!==1||!Array.isArray(o.ships))throw 0;S=o;initCorp();S.speed=0;S.ev=S.ev||[];S.over=!!S.over;save();ui.intro=false;$('#intro').hidden=true;ui.sheet=[];ui.tab='fleet';ui.ask=null;if(S.ships.length){const p=shipPos(S.ships[0]);focusOn(p.lon,p.lat,7,true);}toast(L('Kayıt yüklendi: ','Save loaded: ','已载入存档：')+S.name,'','ok');R();}catch(e){toast(L('Bu dosya bir Armatör kaydı değil','This file is not an Armatör save','该文件不是Armatör存档'),'','bad');}};r.readAsText(file);}
document.addEventListener('change',e=>{const t=e.target;if(t&&t.dataset&&t.dataset.f==='imp'&&t.files&&t.files[0]){importSave(t.files[0]);t.value='';}});

