function renderRot(){const el=$('#rot');if(!el)return;el.innerHTML=`<div><h2>${L('Nasıl oynamak istersin?','How do you want to play?','你想怎么玩？')}</h2><div class="oc"><button type="button" class="oo" data-a="ori" data-v="port">${PH_P}<b>${L('Dikey','Portrait','竖屏')}</b><small>${L('Harita üstte, listeler ve büyük gemi resimleri altta','Map on top, lists and large ship pictures below','地图在上，列表和大幅船舶图片在下')}</small></button><button type="button" class="oo" data-a="ori" data-v="rot">${PH_L}<b>${L('Yatay','Landscape','横屏')}</b><small>${L('Menü solda, harita ortada, panel sağda. Telefonu sola yatırarak tut','Menu on the left, map in the middle, panel on the right. Hold the phone turned to the left','菜单在左，地图居中，面板在右。将手机向左横置')}</small></button></div><p>${L('İstediğin zaman haritadaki döndürme düğmesiyle değiştirebilirsin.','You can switch any time with the rotate button on the map.','随时可以用地图上的旋转按钮切换。')}</p>${langBtns()}</div>`;}
const PWA=(()=>{try{return navigator.standalone===true||matchMedia('(display-mode: standalone)').matches||matchMedia('(display-mode: fullscreen)').matches;}catch(e){return false;}})();
/* iOS ana ekran uygulamasında innerHeight durum çubuğu kadar kısa gelebiliyor; ekranın gerçek boyunu kullan */
function appH(W,H){if(!PWA||!window.screen)return H;const sw=Math.min(screen.width,screen.height),sh=Math.max(screen.width,screen.height);if(Math.abs(W-sw)<=2&&H<sh)return sh;if(Math.abs(W-sh)<=2&&H<sw)return sw;return H;}
function applyOri(){const W=window.innerWidth,H=appH(W,window.innerHeight),por=H>W,p=oriGet(),h=document.documentElement;h.classList.toggle('pwa',PWA);
 h.style.setProperty('--vw',W+'px');h.style.setProperty('--vh',H+'px');
 ROT=por&&p==='rot';ui.port=por&&p==='port';h.classList.toggle('rot',ROT);h.classList.toggle('port',ui.port);$('#rot').hidden=!(por&&!p);
 resizeMap();R();}
/* döndürülmüş ekranda kaydırma: tarayıcı döndürülmüş kutuyu yanlış yönde kaydırır, kaydırmayı biz yaparız */
let TS=null,INR=0,SUP=0;
document.addEventListener('touchstart',e=>{if(!ROT||e.touches.length!==1){TS=null;return;}const el=e.target.closest&&e.target.closest('.scr');if(!el){TS=null;return;}cancelAnimationFrame(INR);const t=e.touches[0];TS={el,x:t.clientX,y:t.clientY,st:el.scrollTop,moved:0,v:0,lx:t.clientX,lt:performance.now()};},{passive:true});
document.addEventListener('touchmove',e=>{if(!ROT||!TS)return;const t=e.touches[0],now=performance.now();if(e.cancelable)e.preventDefault();TS.moved=Math.max(TS.moved,Math.hypot(t.clientX-TS.x,t.clientY-TS.y));
 if(TS.moved>6){TS.el.scrollTop=TS.st-(TS.x-t.clientX);const dt=Math.max(1,now-TS.lt);TS.v=0.7*TS.v+0.3*((TS.lx-t.clientX)/dt);TS.lx=t.clientX;TS.lt=now;}},{passive:false});
document.addEventListener('touchend',()=>{if(!ROT||!TS)return;const T=TS;TS=null;if(T.moved<=6)return;SUP=performance.now();if(performance.now()-T.lt>80)return;let v=T.v,last=performance.now();
 const step=now=>{const dt=now-last;last=now;v*=Math.pow(0.996,dt);if(Math.abs(v)<0.03)return;T.el.scrollTop-=v*dt;INR=requestAnimationFrame(step);};if(Math.abs(v)>0.08)INR=requestAnimationFrame(step);},{passive:true});
document.addEventListener('click',e=>{if(ROT&&performance.now()-SUP<350){e.stopPropagation();e.preventDefault();}},true);

